DROP DATABASE IF EXISTS `tanacsado`;
CREATE DATABASE IF NOT EXISTS `tanacsado`;

USE `tanacsado`;

CREATE TABLE IF NOT EXISTS `szakterulet`(
	`szakterulet_id` int(11) NOT NULL AUTO_INCREMENT,
	`megnevezes` varchar(15) CHARACTER SET utf8 NOT NULL,
 PRIMARY KEY (`szakterulet_id`)
)	ENGINE=InnoDB  DEFAULT CHARSET=utf8 COLLATE=utf8_hungarian_ci AUTO_INCREMENT=6;

INSERT `szakterulet` (`szakterulet_id`, `megnevezes`) VALUES (1, 'állampapír');
INSERT `szakterulet` (`szakterulet_id`, `megnevezes`) VALUES (2, 'kötvény');
INSERT `szakterulet` (`szakterulet_id`, `megnevezes`) VALUES (3, 'részvény');
INSERT `szakterulet` (`szakterulet_id`, `megnevezes`) VALUES (4, 'ingatlan');
INSERT `szakterulet` (`szakterulet_id`, `megnevezes`) VALUES (5, 'forex');

CREATE TABLE IF NOT EXISTS `talalkozo`(
	`talalkozo_id` int(11) NOT NULL AUTO_INCREMENT,
	`tanacsado_id` int(11) NOT NULL,
	`ugyfel_id` int(11) NOT NULL,
	`datum` date NOT NULL,
	`idopont` time NOT NULL,
	`idotartam` int(11) NOT NULL,
 PRIMARY KEY (`talalkozo_id`)
)	ENGINE=InnoDB  DEFAULT CHARSET=utf8 COLLATE=utf8_hungarian_ci AUTO_INCREMENT=523;

